namespace docking.widgets.table;





using docking.widgets.checkbox;

public class GBooleanCellRenderer : GTableCellRenderer {

	protected GCheckBox cb = new GCheckBox();

	public GBooleanCellRenderer() : base()
    {
		setLayout(new BorderLayout());
		cb.setHorizontalAlignment(CENTER);
		cb.setOpaque(false);
		add(cb);
	}

	/* @Override */
	public Component getTableCellRendererComponent(GTableCellRenderingData data) {

		base.getTableCellRendererComponent(data);

		object value = data.getValue();

		JTable table = data.getTable();
		int row = data.getRowViewIndex();
		int col = data.getColumnViewIndex();
		bool isEditable = table.isCellEditable(row, col);

		cb.setEnabled(isEditable);
		setValue(value, isEditable);

		return this;
	}

	public bool isSelected() {
		return cb.isSelected();
	}

	/* @Override */
	public void invalidate() {
		superValidate();
	}

	/* @Override */
	public void validate() {
		lock (getTreeLock()) {
			validateTree();
		}
	}

	/* @Override */
	public Dimension getMaximumSize() {
		return cb.getMaximumSize();
	}

	/* @Override */
	public Dimension getMinimumSize() {
		return cb.getMinimumSize();
	}

	/* @Override */
	public Dimension getPreferredSize() {
		return cb.getPreferredSize();
	}

	protected void setValue(object value, bool isEditable) {
		if (value == null) {
			setText("N/A");
			cb.setVisible(false);
		}
		else {
			setText("");
			cb.setVisible(true);
			bool isSelected = ((Boolean) value).booleanValue();
			cb.setSelected(isSelected);
			setToolTipText(isSelected ? "true" : "false" + (!isEditable ? " (uneditable)" : ""));
		}
	}
}
